import{_ as a,o,c as t,a5 as i}from"./chunks/framework.B6tQOu6W.js";const m=JSON.parse('{"title":"Découpage du TP « Introduction à Laravel » en 4 TP","description":"","frontmatter":{},"headers":[],"relativePath":"plans/mon-tp-introduction-structured-flask.md","filePath":"plans/mon-tp-introduction-structured-flask.md","lastUpdated":null}'),n={name:"plans/mon-tp-introduction-structured-flask.md"};function r(l,e,s,d,c,u){return o(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="decoupage-du-tp-«-introduction-a-laravel-»-en-4-tp" tabindex="-1">Découpage du TP « Introduction à Laravel » en 4 TP <a class="header-anchor" href="#decoupage-du-tp-«-introduction-a-laravel-»-en-4-tp" aria-label="Permalink to &quot;Découpage du TP « Introduction à Laravel » en 4 TP&quot;">​</a></h1><h2 id="contexte" tabindex="-1">Contexte <a class="header-anchor" href="#contexte" aria-label="Permalink to &quot;Contexte&quot;">​</a></h2><p><code>tp/laravel/introduction.md</code> (~1330 lignes) est trop dense : il couvre l&#39;installation, les routes/vues/contrôleurs, la base de données, l&#39;authentification, le rate limiting, Tinker et les factories dans un seul support. Objectif : le découper en 4 TP progressifs, chacun avec sa propre introduction, ses objectifs et des enrichissements pour en faire de « vrais TP ».</p><p>Public cible : étudiants débutants en Laravel ayant fait le TP « Transition vers Laravel » (<code>tp/php/tp6.md</code>) — ils connaissent donc déjà routes, vues, GET/POST, sessions en Laravel, et le PHP pur (sessions, formulaires) de 1re année.</p><p>Décisions actées avec l&#39;utilisateur :</p><ul><li>Le nouveau TP « auth manuelle » devient un <strong>prérequis</strong> du TP Breeze existant (<code>authentification.md</code>), qui reste inchangé.</li><li>Les 3 nouveaux TP <strong>continuent sur le même projet</strong> (fil rouge TODO), avec un encart de rattrapage pour ceux qui n&#39;ont pas le projet précédent.</li></ul><h2 id="decoupage" tabindex="-1">Découpage <a class="header-anchor" href="#decoupage" aria-label="Permalink to &quot;Découpage&quot;">​</a></h2><p>Point de coupe dans <code>introduction.md</code> : la section <code>## La base de données</code> (ligne 634). Tout ce qui précède ne bouge pas.</p><h3 id="_1-tp-laravel-introduction-md-modifie" tabindex="-1">1. <code>tp/laravel/introduction.md</code> (modifié) <a class="header-anchor" href="#_1-tp-laravel-introduction-md-modifie" aria-label="Permalink to &quot;1. `tp/laravel/introduction.md` (modifié)&quot;">​</a></h3><ul><li>Conserver intégralement le début → fin de « Vous en voulez plus ? » (ligne ~631).</li><li>Supprimer tout à partir de <code>## La base de données</code>.</li><li>Ajouter une courte <code>## Conclusion</code> : récap de ce qui a été vu (routes, Blade, layouts, contrôleurs, directives, messages flash, middleware CSRF) + lien vers la suite : « <a href="/tp/laravel/base_de_donnees.html">Laravel &amp; la base de données</a> ». Rappeler de conserver/commiter le projet, il sera réutilisé.</li></ul><h3 id="_2-nouveau-tp-laravel-base-de-donnees-md-—-«-laravel-la-base-de-donnees-»" tabindex="-1">2. Nouveau : <code>tp/laravel/base_de_donnees.md</code> — « Laravel &amp; la base de données » <a class="header-anchor" href="#_2-nouveau-tp-laravel-base-de-donnees-md-—-«-laravel-la-base-de-donnees-»" aria-label="Permalink to &quot;2. Nouveau : `tp/laravel/base_de_donnees.md` — « Laravel &amp; la base de données »&quot;">​</a></h3><p>Contenu repris : sections « La base de données » → « Un formulaire de contact » (lignes 634–978) : SQLite, <code>make:model --migration</code>, migration, <code>$fillable</code>, <code>migrate</code>, Eloquent (all/where/find/create/save/delete), TODO list complète (lister, ajouter, terminer, supprimer), middleware <code>CheckTodo</code>, formulaire de contact.</p><p>Enrichissements :</p><ul><li>Frontmatter <code>description</code>, sommaire <code>[[toc]]</code>, encart « TP guidé » comme l&#39;existant.</li><li>Introduction dédiée : pourquoi un ORM, ce qu&#39;on construit (une TODO list persistante), objectifs listés.</li><li>Section « Reprendre votre projet » : reprendre le projet du TP introduction, avec encart ::: details pour ceux qui partent de zéro (create-project + layout de base minimal).</li><li>Rappel court du vocabulaire : migration / modèle / Eloquent (schéma texte du flux contrôleur → modèle → BDD).</li><li>Questions de compréhension ajoutées aux étapes clés (ex. : à quoi sert la méthode <code>down()</code> ? pourquoi <code>$fillable</code> ? que se passe-t-il si on relance <code>migrate</code> ?).</li><li>Petite section « Vérifier avec SQLite » : ouvrir <code>database/database.sqlite</code> (extension VSCode / DB Browser) pour constater que les données sont bien là.</li><li>Conclusion + lien vers le TP suivant (auth manuelle).</li></ul><h3 id="_3-nouveau-tp-laravel-authentification-manuelle-md-—-«-comprendre-l-authentification-»" tabindex="-1">3. Nouveau : <code>tp/laravel/authentification_manuelle.md</code> — « Comprendre l&#39;authentification » <a class="header-anchor" href="#_3-nouveau-tp-laravel-authentification-manuelle-md-—-«-comprendre-l-authentification-»" aria-label="Permalink to &quot;3. Nouveau : `tp/laravel/authentification_manuelle.md` — « Comprendre l&#39;authentification »&quot;">​</a></h3><p>Contenu repris : sections « Gérer de l&#39;authentification » → « Créer un Middleware pour l&#39;authentification » (lignes 980–1088) : modèle <code>Utilisateur</code>, <code>AuthentificationControleur</code> (login/register + traitements), <code>password_hash</code>/<code>password_verify</code>, session, middleware <code>CheckAuth</code>.</p><p>Enrichissements :</p><ul><li>Introduction théorique <strong>en amont</strong> : principe de l&#39;authentification (identifier ≠ authentifier), pourquoi ne jamais stocker un mot de passe en clair, principe du hash (sens unique, salt), <code>password_hash</code> / <code>password_verify</code>.</li><li><strong>Étape 0 en PHP pur, sans BDD</strong> (demandée par l&#39;utilisateur) : mini-exercice rapide dans un simple fichier <code>auth.php</code> (serveur <code>php -S</code>) — un tableau associatif d&#39;utilisateurs avec mots de passe hashés en dur, un formulaire POST, <code>password_verify</code>, <code>$_SESSION</code>. Objectif : comprendre le mécanisme nu avant la version Laravel. Court (~30 min), guidé, avec questions (que voit-on en base/dans le hash ? deux utilisateurs avec le même mot de passe ont-ils le même hash ?).</li><li>Puis la partie Laravel existante (reprise du projet TODO), enrichie : validation minimale des champs, messages flash d&#39;erreur (réutilise ce qui a été vu au TP intro), route <code>/logout</code>, protection des routes TODO par le middleware <code>CheckAuth</code>.</li><li>Conclusion : ouvrir sur le fait que Laravel sait automatiser tout ça → lien vers le TP Breeze existant (<code>authentification.md</code>) présenté comme la suite logique, et vers le TP conclusion.</li></ul><h3 id="_4-nouveau-tp-laravel-aller-plus-loin-md-—-«-aller-plus-loin-avec-laravel-»-tp-de-conclusion" tabindex="-1">4. Nouveau : <code>tp/laravel/aller_plus_loin.md</code> — « Aller plus loin avec Laravel » (TP de conclusion) <a class="header-anchor" href="#_4-nouveau-tp-laravel-aller-plus-loin-md-—-«-aller-plus-loin-avec-laravel-»-tp-de-conclusion" aria-label="Permalink to &quot;4. Nouveau : `tp/laravel/aller_plus_loin.md` — « Aller plus loin avec Laravel » (TP de conclusion)&quot;">​</a></h3><p>Contenu repris : « Limiter le nombre d&#39;appels » (rate limiting), « Laravel tinker », Bonus 0 (factories/seeders), Bonus 1 (apparence + composants), Bonus 2 (relation Utilisateur ↔ Todo, <code>belongsTo</code>/<code>hasMany</code>), Bonus 3 (pages TODO par utilisateur) — lignes 1090–1333.</p><p>Enrichissements :</p><ul><li>Introduction : ce TP conclut la découverte de Laravel — on consolide le projet TODO (créé au TP BDD, sécurisé au TP auth) en le finissant proprement.</li><li>Prérequis explicites : TP base de données + TP auth manuelle (encart de rattrapage).</li><li>Restructuration : les « Bonus » deviennent des étapes numérotées du TP (rate limiting → Tinker → seeding → relations utilisateur/TODO → filtrage des TODO par utilisateur connecté → pages profil → apparence/composants en bonus final).</li><li>Corriger au passage les coquilles héritées (<code>&#39;completed&#39;</code> → <code>&#39;termine&#39;</code> dans la factory, <code>$todos $utilisateur-&gt;todos;</code> → <code>$todos = $utilisateur-&gt;todos;</code>, « se TP » → « ce TP »).</li><li>Conclusion générale du parcours : récap MVC/Eloquent/auth + orientation vers la suite du parcours (« Eloquent les modèles simplement », projets).</li></ul><h2 id="autres-fichiers-a-modifier" tabindex="-1">Autres fichiers à modifier <a class="header-anchor" href="#autres-fichiers-a-modifier" aria-label="Permalink to &quot;Autres fichiers à modifier&quot;">​</a></h2><ul><li><strong><code>.vitepress/sidebar.ts:238-239</code></strong> : insérer dans « Les TP » après « Introduction à Laravel » : <ul><li>« Laravel &amp; la base de données » → <code>/tp/laravel/base_de_donnees</code></li><li>« Comprendre l&#39;authentification » → <code>/tp/laravel/authentification_manuelle</code></li><li>« Aller plus loin avec Laravel » → <code>/tp/laravel/aller_plus_loin</code> (avant « Laravel &amp; L&#39;authentification » qui reste en place)</li></ul></li><li><strong><code>tp/laravel/authentification.md</code></strong> : petite retouche d&#39;intro uniquement — mentionner que les principes vus dans le TP « auth manuelle » vont être automatisés ici (une phrase + lien). Le reste inchangé.</li><li><code>tp/php/tp6.md</code> et <code>cheatsheets/laravel/quick.md</code> pointent vers <code>introduction.md</code> : liens toujours valides, rien à changer.</li></ul><h2 id="style-conventions-a-respecter" tabindex="-1">Style / conventions à respecter <a class="header-anchor" href="#style-conventions-a-respecter" aria-label="Permalink to &quot;Style / conventions à respecter&quot;">​</a></h2><ul><li>Frontmatter <code>description:</code> en tête de chaque fichier.</li><li><code>::: details Sommaire [[toc]] :::</code> après le titre.</li><li>Encarts VitePress <code>::: tip / warning / danger / details</code>, composant <code>&lt;Reveal text=&quot;…&quot;&gt;</code> pour les solutions.</li><li>Ton existant : tutoiement collectif (« vous »), « Je vous laisse… », « 👋 Si vous avez des questions », questions de compréhension intercalées, code donné partiellement puis « C&#39;est à vous ».</li><li><code>&lt;span v-pre&gt;</code> / <code>&lt;code v-pre&gt;</code> pour les exemples Blade hors blocs de code.</li></ul><h2 id="verification" tabindex="-1">Vérification <a class="header-anchor" href="#verification" aria-label="Permalink to &quot;Vérification&quot;">​</a></h2><ul><li><code>git diff</code> de <code>introduction.md</code> : uniquement des suppressions à partir de la ligne 634 + ajout de la conclusion (le début intact).</li><li>Relire les 3 nouveaux fichiers : chaque TP est autonome (intro, objectifs, prérequis, conclusion, lien vers le suivant).</li><li>Lancer le site (<code>npm run dev</code> / VitePress) et vérifier : les 3 nouvelles entrées du sidebar, le rendu des sommaires <code>[[toc]]</code>, les liens croisés entre les 4 TP, aucun lien mort vers les anciennes ancres de <code>introduction.md</code>.</li></ul>',28)])])}const v=a(n,[["render",r]]);export{m as __pageData,v as default};
